#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void ordina_selezione(int32_t *a, size_t n, uint64_t *cmp) {
    *cmp = 0;
    for (size_t i = 0; i + 1 < n; ++i) {
        size_t min_idx = i;
        for (size_t j = i + 1; j < n; ++j) {
            ++(*cmp);
            if (a[j] < a[min_idx]) { min_idx = j; }
        }
        if (min_idx != i) {
            int32_t t = a[i]; a[i] = a[min_idx]; a[min_idx] = t;
        }
    }
}

static void merge_ric(int32_t *a, int32_t *tmp, size_t sx, size_t dx, uint64_t *cmp) {
    if (dx - sx <= 1) { return; }
    size_t mid = sx + (dx - sx) / 2;
    merge_ric(a, tmp, sx, mid, cmp);
    merge_ric(a, tmp, mid, dx, cmp);
    size_t i = sx, j = mid, k = sx;
    while (i < mid && j < dx) {
        ++(*cmp);
        if (a[i] <= a[j]) { tmp[k++] = a[i++]; } else { tmp[k++] = a[j++]; }
    }
    while (i < mid) { tmp[k++] = a[i++]; }
    while (j < dx) { tmp[k++] = a[j++]; }
    memcpy(a + sx, tmp + sx, (dx - sx) * sizeof(*a));
}

static bool ordina_merge(int32_t *a, size_t n, uint64_t *cmp) {
    *cmp = 0;
    if (n <= 1) { return true; }
    int32_t *tmp = malloc(n * sizeof(*tmp));
    if (tmp == nullptr) { return false; }
    merge_ric(a, tmp, 0, n, cmp);
    free(tmp);
    return true;
}

static bool coppia_forza_bruta(const int32_t *a, size_t n, int64_t target, uint64_t *cmp) {
    *cmp = 0;
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i + 1; j < n; ++j) {
            ++(*cmp);
            if ((int64_t)a[i] + a[j] == target) { return true; }
        }
    }
    return false;
}

static bool coppia_due_indici(const int32_t *a, size_t n, int64_t target, uint64_t *cmp) {
    *cmp = 0;
    if (n < 2) { return false; }
    size_t sx = 0, dx = n - 1;
    while (sx < dx) {
        ++(*cmp);
        int64_t s = (int64_t)a[sx] + a[dx];
        if (s == target) { return true; }
        if (s < target) { ++sx; } else { --dx; }
    }
    return false;
}

static bool leggi_array(const char *p, size_t n, int32_t *out) {
    for (size_t i = 0; i < n; ++i) {
        long v = 0;
        int av = 0;
        if (sscanf(p, "%ld%n", &v, &av) != 1 || v < INT32_MIN || v > INT32_MAX) { return false; }
        out[i] = (int32_t)v;
        p += av;
    }
    return true;
}

int main(void) {
    char riga[1024], cmd[24], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        size_t n = 0;
        int pos = 0;
        long long target = 0;
        int32_t a[128] = {}, b[128] = {};
        uint64_t c1 = 0, c2 = 0;
        if (strcmp(cmd, "SORT") == 0 && sscanf(riga, "SORT %zu%n", &n, &pos) == 1 && n <= 128) {
            if (!leggi_array(riga + pos, n, a)) { return EXIT_FAILURE; }
            if (n > 0) { memcpy(b, a, n * sizeof(int32_t)); }
            ordina_selezione(a, n, &c1);
            if (!ordina_merge(b, n, &c2)) { return EXIT_FAILURE; }
            bool ok = (n == 0 || memcmp(a, b, n * sizeof(int32_t)) == 0);
            printf("SORT(%zu):", n);
            if (n == 0) { printf(" (vuoto)"); }
            for (size_t i = 0; i < n; ++i) { printf(" %" PRId32, b[i]); }
            printf(" | sel_cmp=%" PRIu64 " merge_cmp=%" PRIu64 " ok=%d\n", c1, c2, ok ? 1 : 0);
        } else if (strcmp(cmd, "TWOSUM") == 0 && sscanf(riga, "TWOSUM %lld %zu%n", &target, &n, &pos) == 2 && n <= 128) {
            if (!leggi_array(riga + pos, n, a)) { return EXIT_FAILURE; }
            bool r1 = coppia_forza_bruta(a, n, (int64_t)target, &c1);
            bool r2 = coppia_due_indici(a, n, (int64_t)target, &c2);
            if (r1 != r2) { return EXIT_FAILURE; }
            printf("TWOSUM(%lld): %s | bruta_cmp=%" PRIu64 " lineare_cmp=%" PRIu64 "\n",
                   target, r1 ? "TROVATA" : "ASSENTE", c1, c2);
        } else if (strcmp(cmd, "SCALA") == 0 && sscanf(riga, "SCALA %zu %c", &n, &extra) == 1 && n >= 1 && n <= 128) {
            for (size_t i = 0; i < n; ++i) { a[i] = (int32_t)(n - i); b[i] = a[i]; }
            ordina_selezione(a, n, &c1);
            if (!ordina_merge(b, n, &c2)) { return EXIT_FAILURE; }
            bool ok = (memcmp(a, b, n * sizeof(int32_t)) == 0);
            printf("SCALA(%zu): sel_cmp=%" PRIu64 " merge_cmp=%" PRIu64 " ok=%d\n", n, c1, c2, ok ? 1 : 0);
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    return EXIT_SUCCESS;
}

