#include "heap_gen.h"
#include <stdckdint.h>
#include <stdlib.h>
#include <string.h>

struct heap_gen {
    unsigned char *dati;
    unsigned char *tmp;
    size_t dim_elem;
    size_t len;
    size_t cap;
    heap_cmp_fn cmp;
};

static unsigned char *slot(const heap_gen_t *h, size_t idx) { return h->dati + idx * h->dim_elem; }

static void scambia(heap_gen_t *h, size_t i, size_t j) {
    if (i == j) { return; }
    memcpy(h->tmp, slot(h, i), h->dim_elem);
    memcpy(slot(h, i), slot(h, j), h->dim_elem);
    memcpy(slot(h, j), h->tmp, h->dim_elem);
}

static void risali(heap_gen_t *h, size_t i) {
    while (i > 0) {
        size_t p = (i - 1) / 2;
        if (h->cmp(slot(h, i), slot(h, p)) >= 0) { break; }
        scambia(h, i, p);
        i = p;
    }
}

static void scendi(heap_gen_t *h, size_t i) {
    while (true) {
        size_t sx = 2 * i + 1, dx = sx + 1, migliore = i;
        if (sx < h->len && h->cmp(slot(h, sx), slot(h, migliore)) < 0) { migliore = sx; }
        if (dx < h->len && h->cmp(slot(h, dx), slot(h, migliore)) < 0) { migliore = dx; }
        if (migliore == i) { break; }
        scambia(h, i, migliore);
        i = migliore;
    }
}

static bool assicura_cap(heap_gen_t *h, size_t min_cap) {
    if (min_cap <= h->cap) { return true; }
    size_t nuova = (h->cap == 0) ? 4 : h->cap;
    while (nuova < min_cap) {
        if (ckd_mul(&nuova, nuova, 2)) { return false; }
    }
    size_t byte_tot = 0;
    if (ckd_mul(&byte_tot, nuova, h->dim_elem)) { return false; }
    unsigned char *nb = realloc(h->dati, byte_tot);
    if (nb == nullptr) { return false; }
    h->dati = nb;
    h->cap = nuova;
    return true;
}

heap_gen_t *heap_crea(size_t dim_elem, size_t cap_iniziale, heap_cmp_fn cmp) {
    if (dim_elem == 0 || cmp == nullptr) { return nullptr; }
    heap_gen_t *h = calloc(1, sizeof(*h));
    if (h == nullptr) { return nullptr; }
    h->tmp = malloc(dim_elem);
    if (h->tmp == nullptr) { free(h); return nullptr; }
    h->dim_elem = dim_elem;
    h->cmp = cmp;
    if (cap_iniziale > 0 && !assicura_cap(h, cap_iniziale)) {
        heap_distruggi(h); return nullptr;
    }
    return h;
}

void heap_distruggi(heap_gen_t *h) {
    if (h == nullptr) { return; }
    free(h->dati); free(h->tmp); free(h);
}

bool heap_inserisci(heap_gen_t *h, const void *elem) {
    if (h == nullptr || elem == nullptr || !assicura_cap(h, h->len + 1)) { return false; }
    memcpy(slot(h, h->len), elem, h->dim_elem);
    ++h->len;
    risali(h, h->len - 1);
    return true;
}

bool heap_estrai(heap_gen_t *h, void *out) {
    if (h == nullptr || h->len == 0) { return false; }
    if (out != nullptr) { memcpy(out, slot(h, 0), h->dim_elem); }
    --h->len;
    if (h->len > 0) {
        memcpy(slot(h, 0), slot(h, h->len), h->dim_elem);
        scendi(h, 0);
    }
    return true;
}

bool heap_cima(const heap_gen_t *h, void *out) {
    if (h == nullptr || h->len == 0 || out == nullptr) { return false; }
    memcpy(out, slot(h, 0), h->dim_elem);
    return true;
}

bool heap_costruisci(heap_gen_t *h, const void *dati, size_t n) {
    if (h == nullptr || (n > 0 && dati == nullptr)) { return false; }
    if (n > 0 && !assicura_cap(h, n)) { return false; }
    h->len = n;
    if (n > 0) { memcpy(h->dati, dati, n * h->dim_elem); }
    for (size_t i = n / 2; i > 0; --i) { scendi(h, i - 1); }
    return true;
}

size_t heap_len(const heap_gen_t *h) { return (h != nullptr) ? h->len : 0; }

