#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "heap_gen.h"

typedef struct task {
    int32_t priorita;
    uint32_t ordine;
    char nome[20];
} task_t;

static int cmp_task(const void *a, const void *b) {
    const task_t *ta = a, *tb = b;
    if (ta->priorita != tb->priorita) { return (ta->priorita > tb->priorita) - (ta->priorita < tb->priorita); }
    return (ta->ordine > tb->ordine) - (ta->ordine < tb->ordine);
}

int main(void) {
    heap_gen_t *h = heap_crea(sizeof(task_t), 4, cmp_task);
    if (h == nullptr) { return EXIT_FAILURE; }
    uint32_t seq = 0;
    char riga[128], cmd[16], nome[20], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long prio = 0;
        size_t k = 0;
        if (strcmp(cmd, "PUSH") == 0 && sscanf(riga, "PUSH %ld %19s %c", &prio, nome, &extra) == 2 &&
            prio >= INT32_MIN && prio <= INT32_MAX) {
            task_t t = {.priorita = (int32_t)prio, .ordine = seq++};
            snprintf(t.nome, sizeof(t.nome), "%s", nome);
            if (!heap_inserisci(h, &t)) { heap_distruggi(h); return EXIT_FAILURE; }
        } else if (strcmp(cmd, "PEEK") == 0 && sscanf(riga, "PEEK %c", &extra) != 1) {
            task_t t = {};
            if (heap_cima(h, &t)) { printf("PEEK: %s (prio=%" PRId32 ", ord=%" PRIu32 ")\n", t.nome, t.priorita, t.ordine); }
            else { printf("PEEK: VUOTA\n"); }
        } else if (strcmp(cmd, "POP") == 0 && sscanf(riga, "POP %c", &extra) != 1) {
            task_t t = {};
            if (heap_estrai(h, &t)) { printf("POP: %s (prio=%" PRId32 ", ord=%" PRIu32 ")\n", t.nome, t.priorita, t.ordine); }
            else { printf("POP: VUOTA\n"); }
        } else if (strcmp(cmd, "BUILD") == 0 && sscanf(riga, "BUILD %zu %c", &k, &extra) == 1 && k <= 64) {
            task_t buf[64] = {};
            seq = 0;
            for (size_t i = 0; i < k; ++i) {
                if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
                    sscanf(riga, "%ld %19s %c", &prio, nome, &extra) != 2 ||
                    prio < INT32_MIN || prio > INT32_MAX) { heap_distruggi(h); return EXIT_FAILURE; }
                buf[i] = (task_t){.priorita = (int32_t)prio, .ordine = seq++};
                snprintf(buf[i].nome, sizeof(buf[i].nome), "%s", nome);
            }
            if (!heap_costruisci(h, buf, k)) { heap_distruggi(h); return EXIT_FAILURE; }
            printf("BUILD: n=%zu\n", heap_len(h));
        } else if (strcmp(cmd, "DRAIN") == 0 && sscanf(riga, "DRAIN %c", &extra) != 1) {
            printf("DRAIN:");
            if (heap_len(h) == 0) { printf(" (vuota)\n"); }
            else {
                task_t t = {};
                while (heap_estrai(h, &t)) {
                    printf(" %s(%" PRId32 ",%" PRIu32 ")", t.nome, t.priorita, t.ordine);
                }
                printf("\n");
            }
        } else { heap_distruggi(h); return EXIT_FAILURE; }
    }
    heap_distruggi(h);
    return EXIT_SUCCESS;
}

