#include "avl.h"
#include <stdlib.h>

typedef struct nodo_avl {
    int32_t chiave;
    int32_t valore;
    int altezza;
    struct nodo_avl *sx;
    struct nodo_avl *dx;
} nodo_avl_t;

struct avl {
    nodo_avl_t *radice;
    avl_stats_t st;
};

static int h_nodo(const nodo_avl_t *n) { return (n != nullptr) ? n->altezza : 0; }
static int max_int(int a, int b) { return (a > b) ? a : b; }
static void aggiorna_h(nodo_avl_t *n) { n->altezza = 1 + max_int(h_nodo(n->sx), h_nodo(n->dx)); }
static int fattore_bil(const nodo_avl_t *n) { return (n != nullptr) ? (h_nodo(n->sx) - h_nodo(n->dx)) : 0; }

static nodo_avl_t *ruota_dx(nodo_avl_t *y) {
    nodo_avl_t *x = y->sx;
    y->sx = x->dx;
    x->dx = y;
    aggiorna_h(y);
    aggiorna_h(x);
    return x;
}

static nodo_avl_t *ruota_sx(nodo_avl_t *x) {
    nodo_avl_t *y = x->dx;
    x->dx = y->sx;
    y->sx = x;
    aggiorna_h(x);
    aggiorna_h(y);
    return y;
}

static nodo_avl_t *bilancia(avl_t *t, nodo_avl_t *n) {
    aggiorna_h(n);
    int fb = fattore_bil(n);
    if (fb > 1) {
        if (fattore_bil(n->sx) < 0) {
            ++t->st.rot_lr;
            n->sx = ruota_sx(n->sx);
            return ruota_dx(n);
        }
        ++t->st.rot_ll;
        return ruota_dx(n);
    }
    if (fb < -1) {
        if (fattore_bil(n->dx) > 0) {
            ++t->st.rot_rl;
            n->dx = ruota_dx(n->dx);
            return ruota_sx(n);
        }
        ++t->st.rot_rr;
        return ruota_sx(n);
    }
    return n;
}

static nodo_avl_t *ins_ric(avl_t *t, nodo_avl_t *n, int32_t k, int32_t v, bool *ok) {
    if (n == nullptr) {
        nodo_avl_t *nuovo = malloc(sizeof(*nuovo));
        if (nuovo == nullptr) { *ok = false; return nullptr; }
        *nuovo = (nodo_avl_t){.chiave = k, .valore = v, .altezza = 1};
        ++t->st.n;
        return nuovo;
    }
    if (k < n->chiave) { n->sx = ins_ric(t, n->sx, k, v, ok); }
    else if (k > n->chiave) { n->dx = ins_ric(t, n->dx, k, v, ok); }
    else { n->valore = v; return n; }
    return bilancia(t, n);
}

static nodo_avl_t *minimo(nodo_avl_t *n) {
    while (n->sx != nullptr) { n = n->sx; }
    return n;
}

static nodo_avl_t *del_ric(avl_t *t, nodo_avl_t *n, int32_t k, bool *rimosso) {
    if (n == nullptr) { return nullptr; }
    if (k < n->chiave) { n->sx = del_ric(t, n->sx, k, rimosso); }
    else if (k > n->chiave) { n->dx = del_ric(t, n->dx, k, rimosso); }
    else {
        *rimosso = true;
        if (n->sx == nullptr || n->dx == nullptr) {
            nodo_avl_t *figlio = (n->sx != nullptr) ? n->sx : n->dx;
            free(n);
            --t->st.n;
            return figlio;
        }
        nodo_avl_t *succ = minimo(n->dx);
        n->chiave = succ->chiave;
        n->valore = succ->valore;
        bool dummy = false;
        n->dx = del_ric(t, n->dx, succ->chiave, &dummy);
    }
    return bilancia(t, n);
}

static void distruggi_ric(nodo_avl_t *n) {
    if (n == nullptr) { return; }
    distruggi_ric(n->sx); distruggi_ric(n->dx); free(n);
}

static void inordine_ric(const nodo_avl_t *n, avl_visita_fn fn, void *ctx) {
    if (n == nullptr) { return; }
    inordine_ric(n->sx, fn, ctx); fn(n->chiave, n->valore, ctx); inordine_ric(n->dx, fn, ctx);
}

static bool inv_ric(const nodo_avl_t *n, int64_t lo, int64_t hi, int *h_out) {
    if (n == nullptr) { *h_out = 0; return true; }
    if ((int64_t)n->chiave <= lo || (int64_t)n->chiave >= hi) { return false; }
    int hs = 0, hd = 0;
    if (!inv_ric(n->sx, lo, n->chiave, &hs) || !inv_ric(n->dx, n->chiave, hi, &hd)) { return false; }
    if (n->altezza != 1 + max_int(hs, hd)) { return false; }
    int fb = hs - hd;
    if (fb < -1 || fb > 1) { return false; }
    *h_out = n->altezza;
    return true;
}

avl_t *avl_crea(void) { return calloc(1, sizeof(avl_t)); }
void avl_distruggi(avl_t *t) { if (t != nullptr) { distruggi_ric(t->radice); free(t); } }

bool avl_inserisci(avl_t *t, int32_t chiave, int32_t valore) {
    if (t == nullptr) { return false; }
    bool ok = true;
    t->radice = ins_ric(t, t->radice, chiave, valore, &ok);
    return ok;
}

bool avl_rimuovi(avl_t *t, int32_t chiave) {
    if (t == nullptr) { return false; }
    bool rimosso = false;
    t->radice = del_ric(t, t->radice, chiave, &rimosso);
    return rimosso;
}

bool avl_cerca(const avl_t *t, int32_t chiave, int32_t *valore_out) {
    const nodo_avl_t *c = (t != nullptr) ? t->radice : nullptr;
    while (c != nullptr) {
        if (chiave < c->chiave) { c = c->sx; }
        else if (chiave > c->chiave) { c = c->dx; }
        else { if (valore_out != nullptr) { *valore_out = c->valore; } return true; }
    }
    return false;
}

void avl_inordine(const avl_t *t, avl_visita_fn fn, void *ctx) {
    if (t != nullptr && fn != nullptr) { inordine_ric(t->radice, fn, ctx); }
}

bool avl_verifica_invariante(const avl_t *t) {
    if (t == nullptr) { return false; }
    int h = 0;
    return inv_ric(t->radice, (int64_t)INT32_MIN - 1, (int64_t)INT32_MAX + 1, &h);
}

void avl_statistiche(const avl_t *t, avl_stats_t *st) {
    if (st == nullptr) { return; }
    if (t == nullptr) { *st = (avl_stats_t){}; return; }
    *st = t->st;
    st->altezza = h_nodo(t->radice);
}

