#include "trie.h"
#include <stdlib.h>
#include <string.h>

static constexpr size_t ALFABETO = 26;
static constexpr size_t MAX_LEN = 31;

typedef struct nodo_trie {
    struct nodo_trie *figli[ALFABETO];
    size_t parole_sottoalbero;
    uint32_t peso;
    bool fine_parola;
} nodo_trie_t;

struct trie {
    nodo_trie_t *radice;
    size_t n_nodi;
};

static bool parola_valida(const char *s, bool consenti_vuota) {
    if (s == nullptr) { return false; }
    size_t len = strlen(s);
    if ((!consenti_vuota && len == 0) || len > MAX_LEN) { return false; }
    for (size_t i = 0; i < len; ++i) {
        if (s[i] < 'a' || s[i] > 'z') { return false; }
    }
    return true;
}

static bool ha_figli(const nodo_trie_t *n) {
    for (size_t i = 0; i < ALFABETO; ++i) {
        if (n->figli[i] != nullptr) { return true; }
    }
    return false;
}

static void distruggi_ric(nodo_trie_t *n) {
    if (n == nullptr) { return; }
    for (size_t i = 0; i < ALFABETO; ++i) { distruggi_ric(n->figli[i]); }
    free(n);
}

trie_t *trie_crea(void) {
    trie_t *t = calloc(1, sizeof(*t));
    if (t == nullptr) { return nullptr; }
    t->radice = calloc(1, sizeof(*t->radice));
    if (t->radice == nullptr) { free(t); return nullptr; }
    t->n_nodi = 1;
    return t;
}

void trie_distruggi(trie_t *t) {
    if (t == nullptr) { return; }
    distruggi_ric(t->radice); free(t);
}

static const nodo_trie_t *trova_nodo(const trie_t *t, const char *s) {
    const nodo_trie_t *c = t->radice;
    for (size_t i = 0; s[i] != '\0'; ++i) {
        c = c->figli[(size_t)(s[i] - 'a')];
        if (c == nullptr) { return nullptr; }
    }
    return c;
}

bool trie_cerca(const trie_t *t, const char *parola, uint32_t *peso_out) {
    if (t == nullptr || !parola_valida(parola, false)) { return false; }
    const nodo_trie_t *n = trova_nodo(t, parola);
    if (n == nullptr || !n->fine_parola) { return false; }
    if (peso_out != nullptr) { *peso_out = n->peso; }
    return true;
}

bool trie_inserisci(trie_t *t, const char *parola, uint32_t peso) {
    if (t == nullptr || !parola_valida(parola, false)) { return false; }
    bool esiste = trie_cerca(t, parola, nullptr);
    nodo_trie_t *c = t->radice;
    if (!esiste) { ++c->parole_sottoalbero; }
    for (size_t i = 0; parola[i] != '\0'; ++i) {
        size_t idx = (size_t)(parola[i] - 'a');
        if (c->figli[idx] == nullptr) {
            c->figli[idx] = calloc(1, sizeof(*c->figli[idx]));
            if (c->figli[idx] == nullptr) { return false; }
            ++t->n_nodi;
        }
        c = c->figli[idx];
        if (!esiste) { ++c->parole_sottoalbero; }
    }
    c->fine_parola = true;
    c->peso = peso;
    return true;
}

size_t trie_conta_prefisso(const trie_t *t, const char *prefisso) {
    if (t == nullptr || !parola_valida(prefisso, true)) { return 0; }
    const nodo_trie_t *n = trova_nodo(t, prefisso);
    return (n != nullptr) ? n->parole_sottoalbero : 0;
}

static void sugg_ric(const nodo_trie_t *n, char *buf, size_t prof, size_t max_ris, size_t *trovati, trie_sugg_fn fn, void *ctx) {
    if (n == nullptr || *trovati >= max_ris) { return; }
    if (n->fine_parola) {
        buf[prof] = '\0';
        fn(buf, n->peso, ctx);
        ++(*trovati);
        if (*trovati >= max_ris) { return; }
    }
    for (size_t i = 0; i < ALFABETO && *trovati < max_ris; ++i) {
        if (n->figli[i] != nullptr) {
            buf[prof] = (char)('a' + i);
            sugg_ric(n->figli[i], buf, prof + 1, max_ris, trovati, fn, ctx);
        }
    }
}

size_t trie_suggerisci(const trie_t *t, const char *prefisso, size_t max_ris, trie_sugg_fn fn, void *ctx) {
    if (t == nullptr || fn == nullptr || max_ris == 0 || !parola_valida(prefisso, true)) { return 0; }
    const nodo_trie_t *n = trova_nodo(t, prefisso);
    if (n == nullptr) { return 0; }
    char buf[MAX_LEN + 1] = {};
    size_t len = strlen(prefisso), trovati = 0;
    memcpy(buf, prefisso, len);
    sugg_ric(n, buf, len, max_ris, &trovati, fn, ctx);
    return trovati;
}

static bool rimuovi_ric(trie_t *t, nodo_trie_t *n, const char *s, size_t prof) {
    if (s[prof] == '\0') {
        n->fine_parola = false;
        n->peso = 0;
        --n->parole_sottoalbero;
        return !ha_figli(n);
    }
    size_t idx = (size_t)(s[prof] - 'a');
    bool pota_figlio = rimuovi_ric(t, n->figli[idx], s, prof + 1);
    --n->parole_sottoalbero;
    if (pota_figlio) {
        free(n->figli[idx]);
        n->figli[idx] = nullptr;
        --t->n_nodi;
    }
    return !n->fine_parola && !ha_figli(n);
}

bool trie_rimuovi(trie_t *t, const char *parola) {
    if (t == nullptr || !trie_cerca(t, parola, nullptr)) { return false; }
    (void)rimuovi_ric(t, t->radice, parola, 0);
    return true;
}

size_t trie_num_parole(const trie_t *t) { return (t != nullptr) ? t->radice->parole_sottoalbero : 0; }
size_t trie_num_nodi(const trie_t *t) { return (t != nullptr) ? t->n_nodi : 0; }

