#include "grafo.h"
#include <stdlib.h>

typedef struct arco {
    size_t dest;
    struct arco *prox;
} arco_t;

struct grafo {
    size_t v;
    arco_t **adj;
};

grafo_t *grafo_crea(size_t n_vertici) {
    if (n_vertici == 0) { return nullptr; }
    grafo_t *g = calloc(1, sizeof(*g));
    if (g == nullptr) { return nullptr; }
    g->adj = calloc(n_vertici, sizeof(*g->adj));
    if (g->adj == nullptr) { free(g); return nullptr; }
    g->v = n_vertici;
    return g;
}

void grafo_distruggi(grafo_t *g) {
    if (g == nullptr) { return; }
    for (size_t i = 0; i < g->v; ++i) {
        arco_t *c = g->adj[i];
        while (c != nullptr) {
            arco_t *p = c->prox;
            free(c);
            c = p;
        }
    }
    free(g->adj);
    free(g);
}

size_t grafo_num_vertici(const grafo_t *g) { return (g != nullptr) ? g->v : 0; }

bool grafo_aggiungi_arco(grafo_t *g, size_t u, size_t v) {
    if (g == nullptr || u >= g->v || v >= g->v) { return false; }
    arco_t **cur = &g->adj[u];
    while (*cur != nullptr && (*cur)->dest < v) { cur = &(*cur)->prox; }
    if (*cur != nullptr && (*cur)->dest == v) { return true; }
    arco_t *nuovo = malloc(sizeof(*nuovo));
    if (nuovo == nullptr) { return false; }
    nuovo->dest = v;
    nuovo->prox = *cur;
    *cur = nuovo;
    return true;
}

bool grafo_bfs(const grafo_t *g, size_t sorgente, int32_t *dist_out, size_t *ordine_out, size_t *n_visitati) {
    if (g == nullptr || sorgente >= g->v || dist_out == nullptr || ordine_out == nullptr || n_visitati == nullptr) { return false; }
    size_t *coda = malloc(g->v * sizeof(*coda));
    if (coda == nullptr) { return false; }
    for (size_t i = 0; i < g->v; ++i) { dist_out[i] = -1; }
    size_t testa = 0, fondo = 0, vis = 0;
    dist_out[sorgente] = 0;
    coda[fondo++] = sorgente;
    while (testa < fondo) {
        size_t u = coda[testa++];
        ordine_out[vis++] = u;
        for (const arco_t *a = g->adj[u]; a != nullptr; a = a->prox) {
            if (dist_out[a->dest] == -1) {
                dist_out[a->dest] = dist_out[u] + 1;
                coda[fondo++] = a->dest;
            }
        }
    }
    free(coda);
    *n_visitati = vis;
    return true;
}

static void dfs_ric(const grafo_t *g, size_t u, uint8_t *vis, size_t *ord, size_t *n) {
    vis[u] = 1;
    ord[(*n)++] = u;
    for (const arco_t *a = g->adj[u]; a != nullptr; a = a->prox) {
        if (vis[a->dest] == 0) { dfs_ric(g, a->dest, vis, ord, n); }
    }
}

bool grafo_dfs(const grafo_t *g, size_t sorgente, size_t *ordine_out, size_t *n_visitati) {
    if (g == nullptr || sorgente >= g->v || ordine_out == nullptr || n_visitati == nullptr) { return false; }
    uint8_t *vis = calloc(g->v, 1);
    if (vis == nullptr) { return false; }
    *n_visitati = 0;
    dfs_ric(g, sorgente, vis, ordine_out, n_visitati);
    free(vis);
    return true;
}

static bool topo_ric(const grafo_t *g, size_t u, uint8_t *colore, size_t *post, size_t *n_post) {
    colore[u] = 1;
    for (const arco_t *a = g->adj[u]; a != nullptr; a = a->prox) {
        if (colore[a->dest] == 1) { return false; }
        if (colore[a->dest] == 0 && !topo_ric(g, a->dest, colore, post, n_post)) { return false; }
    }
    colore[u] = 2;
    post[(*n_post)++] = u;
    return true;
}

bool grafo_ordina_topologico(const grafo_t *g, size_t *ordine_out) {
    if (g == nullptr || ordine_out == nullptr) { return false; }
    uint8_t *colore = calloc(g->v, 1);
    size_t *post = malloc(g->v * sizeof(*post));
    if (colore == nullptr || post == nullptr) { free(colore); free(post); return false; }
    size_t n_post = 0;
    bool ok = true;
    for (size_t i = 0; i < g->v && ok; ++i) {
        if (colore[i] == 0) { ok = topo_ric(g, i, colore, post, &n_post); }
    }
    if (ok) {
        for (size_t i = 0; i < g->v; ++i) { ordine_out[i] = post[g->v - 1 - i]; }
    }
    free(colore); free(post);
    return ok;
}

