static unsigned char *el(const coda_prio_t *cp, size_t i) { return cp->dati + i * cp->dim; }

static void scambia(coda_prio_t *cp, size_t i, size_t j) {
    memcpy(cp->tmp, el(cp, i), cp->dim);
    memcpy(el(cp, i), el(cp, j), cp->dim);
