        unsigned char *nb = realloc(cp->dati, tot);
        if (nb == nullptr) { return false; }
        cp->dati = nb; cp->cap = nuova;
    }
    size_t i = cp->len++;
    memcpy(el(cp, i), elem, cp->dim);
    while (i > 0) {
        size_t p = (i - 1) / 2;
        if (cp->cmp(el(cp, i), el(cp, p)) >= 0) { break; }
        scambia(cp, i, p); i = p;
    }
    return true;
}

bool cp_estrai(coda_prio_t *cp, void *out) {
    if (cp == nullptr || cp->len == 0) { return false; }
    if (out != nullptr) { memcpy(out, el(cp, 0), cp->dim); }
    --cp->len;
    if (cp->len > 0) {
        memcpy(el(cp, 0), el(cp, cp->len), cp->dim);
        size_t i = 0;
        while (true) {
            size_t sx = 2 * i + 1, dx = sx + 1, m = i;
            if (sx < cp->len && cp->cmp(el(cp, sx), el(cp, m)) < 0) { m = sx; }
            if (dx < cp->len && cp->cmp(el(cp, dx), el(cp, m)) < 0) { m = dx; }
            if (m == i) { break; }
            scambia(cp, i, m); i = m;
        }
    }
    return true;
}

bool cp_vuota(const coda_prio_t *cp) { return cp == nullptr || cp->len == 0; }

