#include "dijkstra.h"
#include "coda_prio.h"
#include <stdckdint.h>
#include <stdlib.h>

typedef struct arco_p {
    size_t dest;
    uint64_t peso;
    struct arco_p *prox;
} arco_p_t;

struct grafo_pesato {
    size_t v;
    arco_p_t **adj;
};

typedef struct voce_dijk {
    uint64_t dist;
    size_t v;
} voce_dijk_t;

static int cmp_voce(const void *a, const void *b) {
    const voce_dijk_t *va = a, *vb = b;
    if (va->dist != vb->dist) { return (va->dist > vb->dist) - (va->dist < vb->dist); }
    return (va->v > vb->v) - (va->v < vb->v);
}

grafo_pesato_t *gp_crea(size_t n_vertici) {
    if (n_vertici == 0) { return nullptr; }
    grafo_pesato_t *g = calloc(1, sizeof(*g));
    if (g == nullptr) { return nullptr; }
    g->adj = calloc(n_vertici, sizeof(*g->adj));
    if (g->adj == nullptr) { free(g); return nullptr; }
    g->v = n_vertici;
    return g;
}

void gp_distruggi(grafo_pesato_t *g) {
    if (g == nullptr) { return; }
    for (size_t i = 0; i < g->v; ++i) {
        arco_p_t *c = g->adj[i];
        while (c != nullptr) { arco_p_t *p = c->prox; free(c); c = p; }
    }
    free(g->adj); free(g);
}

size_t gp_num_vertici(const grafo_pesato_t *g) { return (g != nullptr) ? g->v : 0; }

bool gp_aggiungi_arco(grafo_pesato_t *g, size_t u, size_t v, int64_t peso) {
    if (g == nullptr || u >= g->v || v >= g->v || peso < 0) { return false; }
    arco_p_t *a = malloc(sizeof(*a));
    if (a == nullptr) { return false; }
    a->dest = v; a->peso = (uint64_t)peso; a->prox = g->adj[u];
    g->adj[u] = a;
    return true;
}

bool gp_dijkstra(const grafo_pesato_t *g, size_t sorgente, uint64_t *dist_out, int32_t *prec_out) {
    if (g == nullptr || sorgente >= g->v || dist_out == nullptr || prec_out == nullptr) { return false; }
    for (size_t i = 0; i < g->v; ++i) { dist_out[i] = UINT64_MAX; prec_out[i] = -1; }
    coda_prio_t *cp = cp_crea(sizeof(voce_dijk_t), cmp_voce);
    if (cp == nullptr) { return false; }
    dist_out[sorgente] = 0;
    voce_dijk_t ini = {.dist = 0, .v = sorgente};
    if (!cp_inserisci(cp, &ini)) { cp_distruggi(cp); return false; }
    voce_dijk_t cur = {};
    while (cp_estrai(cp, &cur)) {
        if (cur.dist > dist_out[cur.v]) { continue; }
        for (const arco_p_t *a = g->adj[cur.v]; a != nullptr; a = a->prox) {
            uint64_t nd = 0;
            if (ckd_add(&nd, cur.dist, a->peso)) { continue; }
            if (nd < dist_out[a->dest]) {
                dist_out[a->dest] = nd;
                prec_out[a->dest] = (int32_t)cur.v;
                voce_dijk_t nv = {.dist = nd, .v = a->dest};
                if (!cp_inserisci(cp, &nv)) { cp_distruggi(cp); return false; }
            }
        }
    }
    cp_distruggi(cp);
    return true;
}

bool gp_ricostruisci_cammino(const int32_t *prec, size_t sorgente, size_t dest, size_t *cammino_out, size_t *len_out) {
    if (prec == nullptr || cammino_out == nullptr || len_out == nullptr) { return false; }
    size_t k = 0, cur = dest;
    while (true) {
        cammino_out[k++] = cur;
        if (cur == sorgente) { break; }
        if (prec[cur] < 0) { return false; }
        cur = (size_t)prec[cur];
    }
    for (size_t i = 0; i < k / 2; ++i) {
        size_t t = cammino_out[i]; cammino_out[i] = cammino_out[k - 1 - i]; cammino_out[k - 1 - i] = t;
    }
    *len_out = k;
    return true;
}

