#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "dijkstra.h"

static void stampa_cammino(const size_t *cam, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        printf("%s%zu", (i == 0) ? "" : "->", cam[i]);
    }
}

int main(void) {
    grafo_pesato_t *g = nullptr;
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t u = 0, v = 0;
        long long peso = 0;
        if (strcmp(cmd, "INIT") == 0 && sscanf(riga, "INIT %zu %c", &v, &extra) == 1 && v >= 1 && v <= 64) {
            gp_distruggi(g);
            g = gp_crea(v);
            if (g == nullptr) { return EXIT_FAILURE; }
            printf("INIT: V=%zu\n", v);
        } else if (strcmp(cmd, "EDGE") == 0 && g != nullptr && sscanf(riga, "EDGE %zu %zu %lld %c", &u, &v, &peso, &extra) == 3) {
            if (peso < 0) { printf("EDGE: PESO NEGATIVO RIFIUTATO\n"); }
            else if (!gp_aggiungi_arco(g, u, v, (int64_t)peso)) { gp_distruggi(g); return EXIT_FAILURE; }
        } else if (strcmp(cmd, "DIJKSTRA") == 0 && g != nullptr && sscanf(riga, "DIJKSTRA %zu %c", &u, &extra) == 1) {
            uint64_t dist[64] = {}; int32_t prec[64] = {}; size_t cam[64] = {}, len = 0;
            if (!gp_dijkstra(g, u, dist, prec)) { gp_distruggi(g); return EXIT_FAILURE; }
            printf("DIJKSTRA(%zu):\n", u);
            for (size_t i = 0; i < gp_num_vertici(g); ++i) {
                if (dist[i] == UINT64_MAX) {
                    printf("  v=%zu dist=INF cammino=IRRAGGIUNGIBILE\n", i);
                } else {
                    gp_ricostruisci_cammino(prec, u, i, cam, &len);
                    printf("  v=%zu dist=%" PRIu64 " cammino=", i, dist[i]);
                    stampa_cammino(cam, len);
                    printf("\n");
                }
            }
        } else if (strcmp(cmd, "PATH") == 0 && g != nullptr && sscanf(riga, "PATH %zu %zu %c", &u, &v, &extra) == 2 && v < gp_num_vertici(g)) {
            uint64_t dist[64] = {}; int32_t prec[64] = {}; size_t cam[64] = {}, len = 0;
            if (!gp_dijkstra(g, u, dist, prec)) { gp_distruggi(g); return EXIT_FAILURE; }
            if (dist[v] == UINT64_MAX) {
                printf("PATH(%zu->%zu): IRRAGGIUNGIBILE\n", u, v);
            } else {
                gp_ricostruisci_cammino(prec, u, v, cam, &len);
                printf("PATH(%zu->%zu): dist=%" PRIu64 " cammino=", u, v, dist[v]);
                stampa_cammino(cam, len);
                printf("\n");
            }
        } else { gp_distruggi(g); return EXIT_FAILURE; }
    }
    gp_distruggi(g);
    return EXIT_SUCCESS;
}
